import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const fresh = async () => (await createHost()) as any;

test('initial state', async () => {
  const h = await fresh();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle' });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nobody'), null);
  assert.equal((await h.workDone('worker0')).ok, false);
  assert.equal((await h.workDone('nobody')).ok, false);
  assert.equal((await h.cancel()).ok, false);
});

test('start sends Assign and both complete', async () => {
  const h = await fresh();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m: any) => [m.from, m.to, m.action, m.data]).sort(),
    [['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0'), { ok: true });
  const [r] = await h.inFlight();
  assert.deepEqual([r.from, r.to, r.action, r.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]);
  await h.deliver(r.id);
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned' });
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed' });
});

test('failure', async () => {
  const h = await fresh();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1'); await h.workDone('worker0'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'completed', task1: 'failed' });
});

test('cancel aborts only assigned tasks', async () => {
  const h = await fresh();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0'); await h.deliverAll();
  assert.deepEqual(await h.cancel(), { ok: true });
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m: any) => [m.to, m.action]), [['worker1', 'Abort']]);
  assert.deepEqual((await h.run()).status, 'cancelling');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'completed', task1: 'cancelled' });
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('cancel races with done', async () => {
  const h = await fresh();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0'); // report in flight
  await h.cancel();             // Abort to both, task0 still assigned
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'completed', task1: 'cancelled' });
});

test('cancel before Assign arrives', async () => {
  const h = await fresh();
  await h.start();
  await h.cancel();
  const aborts = (await h.inFlight()).filter((m: any) => m.action === 'Abort');
  for (const a of aborts) await h.deliver(a.id);
  assert.deepEqual(await h.run(), { status: 'cancelling', task0: 'assigned', task1: 'assigned' });
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workFailed('worker0'); await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed' });
});

