test('failure', async () => {
  const h = await fresh();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1'); await h.workDone('worker0'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'completed', task1: 'failed' });
});

input.new_string:
test('first failure is retried, second is recorded', async () => {
  const h = await fresh();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1'); await h.workDone('worker0');
  const reps = (await h.inFlight()).filter((m: any) => m.to === 'run');
  for (const r of reps) await h.deliver(r.id);
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned', retried0: false, retried1: true });
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m: any) => [m.from, m.to, m.action, m.data]), [['run', 'worker1', 'Assign', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workFailed('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'completed', task1: 'failed', retried0: false, retried1: true });
});

test('retried task can complete', async () => {
  const h = await fresh();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0'); await h.deliverAll();
  await h.workDone('worker0'); await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: true, retried1: false });
});

test('failure while cancelling is not retried', async () => {
  const h = await fresh();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'cancelled', retried0: false, retried1: false });
});

