test('taskTimeout refusals', async () => {
  const h = await fresh();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start();
  assert.equal((await h.taskTimeout(2)).ok, false);
  assert.equal((await h.taskTimeout(-1)).ok, false);
  assert.deepEqual(await h.taskTimeout(1), { ok: true });
  assert.equal((await h.taskTimeout(1)).ok, false);
});

test('timeout fails the task, aborts the worker, ignores the late report', async () => {
  const h = await fresh();
  await h.start(); await h.deliverAll();
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.deepEqual(await h.run(), { status: 'running', task0: 'failed', task1: 'assigned', retried0: false, retried1: false });
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m: any) => [m.from, m.to, m.action, m.data]), [['run', 'worker0', 'Abort', {}]]);
  await h.deliverAll(); // worker0 aborts and reports cancelled, which is ignored
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.deepEqual(await h.run(), { status: 'running', task0: 'failed', task1: 'assigned', retried0: false, retried1: false });
  await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed', retried0: false, retried1: false });
});

